41	 * decorator form (`@RequestContext()`) is preferred for controllers, since
42	 * request-scoped injection makes the injecting provider request-scoped.
43	 */
44	const requestContextProvider = {
45	  provide: REQUEST_CONTEXT,
46	  scope: Scope.REQUEST,
47	  inject: [REQUEST],
48	  useFactory: (request: unknown): RequestContextSnapshot | undefined =>
49	    readSnapshot(request),
50	};
