76	  providers: [
77	    RequestContextHost,
78	    RequestContextInterceptor,
79	    {
80	      provide: APP_INTERCEPTOR,
81	      useExisting: RequestContextInterceptor,
82	    },
83	    requestContextProvider,
84	  ],
85	  exports: [RequestContextHost, REQUEST_CONTEXT],
