356	function isPromiseLike(value: unknown): value is PromiseLike<unknown> {
357	  return (
358	    !!value &&
359	    (typeof value === 'object' || typeof value === 'function') &&
360	    typeof (value as PromiseLike<unknown>).then === 'function'
361	  );
