1	import {
2	  BadRequestException,
3	  Controller,
4	  Get,
5	  Query,
6	  Req,
7	} from '@nestjs/common';
8	import {
9	  RequestContext,
10	  RequestContextHost,
11	  type RequestContextSnapshot,
12	} from '@nestjs/core';
13	import { AsyncRecordsStore } from '../shared/async-records.store.js';
14	import { FilteredProbeError } from '../shared/filtered-probe.error.js';
15	import {
16	  ASYNC_CONTEXT_ROUTE,
17	  HEALTH_ROUTE,
18	  RELEASE_GATES_ROUTE,
19	} from '../shared/routes.js';
20	import { SingletonProbeService } from '../shared/singleton-probe.service.js';
21	
22	/**
23	 * Probe controller backing the request-context integration tests.
24	 *
25	 * - `GET /async-context?marker=...` writes the marker into the request
26	 *   snapshot, crosses an asynchronous boundary while reading it back,
27	 *   registers one or more post-response continuations (each parked behind a
28	 *   per-continuation gate until tests release it) and completes the
29	 *   response.
30	 * - `GET /async-records` (see {@link AsyncRecordsController}) reads back
31	 *   every continuation with its current lifecycle state.
32	 * - `GET /release-gates[?id=...]` releases parked continuation gates.
33	 */
34	@Controller()
35	export class AsyncContextController {
36	  constructor(
37	    private readonly records: AsyncRecordsStore,
38	    private readonly contextHost: RequestContextHost,
39	    private readonly singletonProbe: SingletonProbeService,
40	  ) {}
41	
42	  @Get(ASYNC_CONTEXT_ROUTE)
43	  public async probe(
44	    @Query('marker') marker: string | undefined,
45	    @Query('registrations') registrations: string | undefined,
46	    @Query('fail') fail: string | undefined,
47	    @Query('failCallbackIndex') failCallbackIndex: string | undefined,
48	    @Query('delayMs') delayMs: string | undefined,
49	    @RequestContext() context: RequestContextSnapshot | undefined,
50	    @Req() request: unknown,
51	  ): Promise<{
52	    contextId: string;
53	    marker: string;
54	    readConsistent: boolean;
55	    belongsToCurrentRequest: boolean;
56	    continuationIds: string[];
57	    aborted?: boolean;
58	  }> {
59	    if (!context) {
60	      throw new Error('Request context snapshot was not attached');
61	    }
62	    if (typeof marker !== 'string' || marker.length === 0) {
63	      throw new BadRequestException('marker query parameter is required');
64	    }
65	
66	    // Fixed sequence: write first, then cross an async wait and read back.
67	    context.set('marker', marker);
68	    const readBeforeAwait = context.get<string>('marker');
69	    await Promise.resolve();
70	    const readAfterAwait = context.get<string>('marker');
71	
72	    // After the await the async-local continuation must still resolve to
73	    // this snapshot, and the snapshot attached to the platform request must
74	    // be the very same instance.
75	    const currentFromContinuation = this.contextHost.current();
76	    const attachedToRequest = this.contextHost.getForRequest(request);
77	    const belongsToCurrentRequest =
78	      currentFromContinuation === context && attachedToRequest === context;
79	
80	    const count = clampRegistrations(registrations);
81	    const failingIndex = parseOptionalIndex(failCallbackIndex);
82	    const continuationIds: string[] = [];
83	
84	    for (let index = 0; index < count; index++) {
85	      const registrationIndex = index;
86	      const continuationId = this.records.register(context.id, marker);
87	
88	      context.registerAfterTerminated(
89	        async (snapshot: RequestContextSnapshot) => {
90	          try {
91	            // The body stays parked until the test releases the gate. Until
92	            // then `/async-records` reports `pending`, which also covers
93	            // "callback registered but not finished yet".
94	            await this.records.waitForGate(continuationId);
95	
96	            if (fail === 'continuation' || failingIndex === registrationIndex) {
97	              throw new Error(`intentional continuation failure: ${marker}`);
98	            }
99	
100	            const firstRead = snapshot.get<string>('marker') ?? null;
101	            await Promise.resolve();
102	            const secondRead = snapshot.get<string>('marker') ?? null;
103	
104	            // A write attempted after the freeze must be rejected and must
105	            // not change the value read back afterwards.
106	            const lateWriteAccepted = snapshot.set('lateWrite', marker);
107	            const thirdRead = snapshot.get<string>('marker') ?? null;
108	
109	            this.records.markCompleted(continuationId, {
110	              frozenValue: firstRead,
111	              frozenValueStable:
112	                firstRead === marker &&
113	                secondRead === marker &&
114	                thirdRead === marker &&
115	                !lateWriteAccepted,
116	              lateWriteAccepted,
117	            });
118	          } catch (error) {
119	            // A failing continuation fails only its own record; sibling
120	            // continuations and other requests are untouched.
121	            this.records.markFailed(continuationId, error);
122	          }
123	        },
124	      );
125	
126	      continuationIds.push(continuationId);
127	    }
